def _kingdomhearts2worldgen_hb_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Membership Card', player, Amount)


def _kingdomhearts2worldgen_ht_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Bone Fist', player, Amount)


def _kingdomhearts2worldgen_hundred_acre_unlocked(state: "CollectionState", player: int, amount = None) -> bool:
    return state.has('Torn Page', player, amount)


def _kingdomhearts2worldgen_kh2_can_reach(state: "CollectionState", player: int, loc = None) -> bool:
    return state.can_reach(state.multiworld.get_location(loc, player), 'location', player)


def _kingdomhearts2worldgen_kh2_can_reach_any(state: "CollectionState", player: int, loc_set = None) -> bool:
    if loc_set is None:
        return False
    multiworld = state.multiworld
    for loc_name in loc_set:
        try:
            location = multiworld.get_location(loc_name, player)
            if location.can_reach(state):
                return True
        except KeyError:
            # Location doesn't exist, skip it
            continue
    return False


def _kingdomhearts2worldgen_kh2_dict_count(state: "CollectionState", player: int, item_name_to_count = None) -> bool:
    return True


def _kingdomhearts2worldgen_kh2_dict_one_count(state: "CollectionState", player: int, item_name_to_count = None) -> int:
    return sum(1 for [item_name, item_amount] in item_name_to_count.items() if (state.count(item_name, player) >= item_amount))


def _kingdomhearts2worldgen_kh2_has_all(state: "CollectionState", player: int, items = None) -> bool:
    if items is None:
        items = ()
    return state.has_all(items, player)


def _kingdomhearts2worldgen_kh2_has_any(state: "CollectionState", player: int, items = None) -> bool:
    if items is None:
        items = ()
    return state.has_any(items, player)


def _kingdomhearts2worldgen_kh2_list_any_sum(state: "CollectionState", player: int, list_of_item_name_list = None) -> int:
    if list_of_item_name_list is None:
        return 0
    return sum(1 for item_list in list_of_item_name_list if state.has_any(item_list, player))


def _kingdomhearts2worldgen_kh2_list_count_sum(state: "CollectionState", player: int, item_name_set = None) -> int:
    return sum(state.count(item_name, player) for item_name in item_name_set)


